<template>
  <div>
    <input v-model="query" @keyup.enter="searchVideos" placeholder="Search for videos" />
    <button @click="searchVideos">Search</button>
    
    <div v-if="filteredVideos.length > 0">
      <ul>
        <li v-for="video in filteredVideos" :key="video.id">
          <a href="#" @click="playVideo(video.id)">
            <img :src="'https://img.youtube.com/vi/' + video.id + '/default.jpg'" :alt="video.title" />
            <p>{{ video.title }}</p>
          </a>
        </li>
      </ul>
    </div>

    <div v-if="selectedVideoId">
      <iframe
        width="560"
        height="315"
        :src="'https://www.youtube.com/embed/' + selectedVideoId"
        frameborder="0"
        allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
        allowfullscreen
      ></iframe>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      query: '',
      selectedVideoId: null,
      videos: [
        { id: 'dQw4w9WgXcQ', title: 'Never Gonna Give You Up' },
        { id: '9bZkp7q19f0', title: 'Gangnam Style' },
        { id: 'LsoLEjrDogU', title: 'Shape of You' },
        { id: 'nCkpzqqOg9A', title: 'Despacito' },
        { id: 'fJ9rUzIMcZQ', title: 'Bohemian Rhapsody' },
        // Add more predefined video IDs
      ],
    };
  },
  computed: {
    filteredVideos() {
      return this.videos.filter(video =>
        video.title.toLowerCase().includes(this.query.toLowerCase())
      );
    },
  },
  methods: {
    playVideo(videoId) {
      this.selectedVideoId = videoId;
    },
    searchVideos() {
      // Trigger search by updating the filtered videos
    },
  },
};
</script>

<style scoped>
input {
  margin-right: 10px;
}
iframe {
  margin-top: 20px;
}
</style>
